  ],
  "commercial_requirements": [
    {"text": "Services billed on Time & Material (T&M) basis...", "pages": [45]}
  ],
  "project_duration": [],
  "important_conditions": [
    {"text": "Confidentiality and non-disclosure obligations apply...", "pages": [67]}
  ]
}

